insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'memory-palace-challenge'), 'overall', 0, 30, 'Developing', convert_from(decode('T3JkZXJlZCByZWNhbGwgYWNyb3NzIGEgZnVsbCByb3V0ZSBpcyBkaWZmaWN1bHQgcmlnaHQgbm93IOKAlCB0aGUgdGVjaG5pcXVlIGl0c2VsZiB0YWtlcyBwcmFjdGljZSBiZWZvcmUgdGhlIHBhbGFjZSAic3RpY2tzLiI=', 'base64'), 'UTF8'), ARRAY['Start with shorter routes (3-4 stops) and build up gradually', 'Make the mental images vivid and slightly absurd — bizarre images are easier to recall than plain ones', 'Walk the route in your head at least twice before attempting recall']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'memory-palace-challenge'), 'overall', 31, 50, 'Average', 'Shorter routes are manageable, but longer ones or a route studied only once lose items partway through.', ARRAY['Practice the same route repeatedly until the order feels automatic before moving to a new one', 'Use real, familiar locations (your actual home) instead of generic ones — familiarity anchors the route']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'memory-palace-challenge'), 'overall', 51, 70, 'Strong', 'Reliable ordered recall across most routes, with occasional slips on the longer ones.', ARRAY['Push route length further — competitive memory athletes use routes with dozens of stops', convert_from(decode('UHJhY3RpY2UgcmVjYWxsaW5nIHJvdXRlcyBvdXQgb2Ygb3JkZXIgKGUuZy4gIndoYXQgd2FzIGF0IHN0b3AgNT8iKSB0byBzdHJlbmd0aGVuIHRoZSB1bmRlcmx5aW5nIHNwYXRpYWwgbWFwLCBub3QganVzdCB0aGUgc2VxdWVuY2U=', 'base64'), 'UTF8')]::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'memory-palace-challenge'), 'overall', 71, 85, 'Very Strong', 'Consistently accurate ordered recall even on the longest route, with strong position accuracy too.', ARRAY['This technique scales well — try applying it to real material you need to memorize (a speech, a list, key facts)', convert_from(decode('QnVpbGQgbXVsdGlwbGUgcGFsYWNlcyBmb3IgZGlmZmVyZW50IHRvcGljcyBzbyB0aGV5IGRvbid0IGludGVyZmVyZSB3aXRoIGVhY2ggb3RoZXI=', 'base64'), 'UTF8')]::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'memory-palace-challenge'), 'overall', 86, 100, 'Exceptional', 'Near-perfect ordered recall across every route — the core skill behind competitive memory-sport performance.', ARRAY[convert_from(decode('VGhpcyBpcyBnZW51aW5lbHkgY29tcGV0aXRpb24tbGV2ZWwgc2VyaWFsIHJlY2FsbCDigJQgdGhlIFdvcmxkIE1lbW9yeSBDaGFtcGlvbnNoaXBzJyBkaXNjaXBsaW5lcyB1c2UgdGhlIHNhbWUgY29yZSB0ZWNobmlxdWUgYXQgbGFyZ2VyIHNjYWxl', 'base64'), 'UTF8'), 'Consider extending routes further, or memorizing genuinely long real-world sequences']::text[], NULL, 5);
